package sample

import "errors"

type Calculator struct {
	base int
}

func NewCalculator(base int) *Calculator {
	return &Calculator{base: base}
}

func (c *Calculator) Add(a, b int) int {
	return c.base + a + b
}

func subtract(a, b int) (int, error) {
	if a < b {
		return 0, errors.New("a < b")
	}
	return a - b, nil
}
EOF"}

