{"command":"cat <<'EOF' > /tmp/test_gotests/generics.go
package sample

import "errors"

var ErrNotFound = errors.New("not found")

func FindFirst[T comparable](slice []T, target T) (int, error) {
	for i, v := range slice {
		if v == target {
			return i, nil
		}
	}
	return -1, ErrNotFound
}

type Set[T comparable] struct {
	m map[T]struct{}
}

func (s *Set[T]) Add(v T) {
	if s.m == nil {
		s.m = make(map[T]struct{})
	}
	s.m[v] = struct{}{}
}

func MapKeys[K comparable, V any](m map[K]V) []K {
	keys := make([]K, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	return keys
}

type Number interface {
	~int | ~int64 | ~float64
}

func Sum[T Number](vals []T) T {
	var total T
	for _, v := range vals {
		total += v
	}
	return total
}
EOF

./executable -all /tmp/test_gotests/generics.go 1> /tmp/stdout.txt
cat /tmp/stdout.txt"}

