{"command":"cat <<'EOF' > parser/parser.go
package parser

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"

	"gotests/models"
)

type Parser struct {
	fset *token.FileSet
}

func New() *Parser {
	return &Parser{
		fset: token.NewFileSet(),
	}
}

func (p *Parser) Parse(path string) (*models.Header, []*models.Function, error) {
	fi, err := os.Stat(path)
	if err != nil {
		return nil, nil, fmt.Errorf("input.Files: os.Stat: %w", err)
	}

	if fi.IsDir() {
		return nil, nil, fmt.Errorf("%s is a directory", path)
	}

	node, err := parser.ParseFile(p.fset, path, nil, parser.ParseComments)
	if err != nil {
		return nil, nil, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %w", err)
	}

	structs := make(map[string][]*models.Field)
	for _, decl := range node.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.TYPE {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			st, ok := ts.Type.(*ast.StructType)
			if !ok || st.Fields == nil {
				continue
			}
			var fields []*models.Field
			fieldIdx := 0
			for _, field := range st.Fields.List {
				typeExpr := parseExpr(field.Type)
				if len(field.Names) == 0 {
					// embedded field
					typeName := typeExpr.Value
					if strings.HasPrefix(typeName, "*") {
						typeName = typeName[1:]
					}
					if idx := strings.LastIndex(typeName, "."); idx != -1 {
						typeName = typeName[idx+1:]
					}
					fields = append(fields, &models.Field{
						Name:  typeName,
						Type:  typeExpr,
						Index: fieldIdx,
					})
					fieldIdx++
				} else {
					for _, name := range field.Names {
						fields = append(fields, &models.Field{
							Name:  name.Name,
							Type:  typeExpr,
							Index: fieldIdx,
						})
						fieldIdx++
					}
				}
			}
			structs[ts.Name.Name] = fields
		}
	}

	// Extract comments before package clause
	var comments []string
	if node.Doc != nil {
		for _, c := range node.Doc.List {
			comments = append(comments, c.Text)
		}
	}

	header := &models.Header{
		Package:  node.Name.Name,
		Comments: comments,
	}

	for _, imp := range node.Imports {
		name := ""
		if imp.Name != nil {
			name = imp.Name.Name
		}
		pathVal := imp.Path.Value
		header.Imports = append(header.Imports, &models.Import{
			Name: name,
			Path: pathVal,
		})
	}

	var funcs []*models.Function
	for _, decl := range node.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}

		fn := &models.Function{
			Name:       fd.Name.Name,
			IsExported: models.IsExported(fd.Name.Name),
		}

		// Type parameters
		typeParamMap := make(map[string]string)
		if fd.Type.TypeParams != nil {
			for _, tp := range fd.Type.TypeParams.List {
				constraintStr := parseExpr(tp.Type).Value
				for _, name := range tp.Names {
					concrete := mapTypeConstraint(constraintStr)
					typeParamMap[name.Name] = concrete
					fn.TypeParams = append(fn.TypeParams, &models.Field{
						Name: name.Name,
						Type: &models.Expression{Value: concrete},
					})
				}
			}
		}

		// Receiver
		if fd.Recv != nil && len(fd.Recv.List) > 0 {
			rf := fd.Recv.List[0]
			recvTypeExpr := parseExpr(rf.Type)
			recvName := ""
			if len(rf.Names) > 0 {
				recvName = rf.Names[0].Name
			}

			// check generic receiver
			if idx := strings.IndexByte(recvTypeExpr.Value, '['); idx != -1 {
				// e.g. *Set[T] or Set[T]
				rawType := recvTypeExpr.Value[:idx]
				if closeIdx := strings.IndexByte(recvTypeExpr.Value, ']'); closeIdx != -1 {
					targs := recvTypeExpr.Value[idx+1 : closeIdx]
					for _, targ := range strings.Split(targs, ",") {
						targ = strings.TrimSpace(targ)
						if targ != "" {
							if concrete, ok := typeParamMap[targ]; ok {
								recvTypeExpr.Value = strings.Replace(recvTypeExpr.Value, targ, concrete, 1)
							} else {
								recvTypeExpr.Value = strings.Replace(recvTypeExpr.Value, targ, "string", 1)
							}
						}
					}
				}
				_ = rawType
			}

			recv := &models.Receiver{
				Field: models.Field{
					Name: recvName,
					Type: recvTypeExpr,
				},
			}
			typeName := recv.TypeName()
			if fields, exists := structs[typeName]; exists {
				recv.Fields = fields
			}
			fn.Receiver = recv
		}

		// Parameters
		if fd.Type.Params != nil {
			paramIdx := 0
			for _, field := range fd.Type.Params.List {
				expr := parseExpr(field.Type)
				expr = instantiateExpr(expr, typeParamMap)

				if len(field.Names) == 0 {
					fn.Parameters = append(fn.Parameters, &models.Field{
						Name:  fmt.Sprintf("in%d", paramIdx),
						Type:  expr,
						Index: paramIdx,
					})
					paramIdx++
				} else {
					for _, name := range field.Names {
						fn.Parameters = append(fn.Parameters, &models.Field{
							Name:  name.Name,
							Type:  expr,
							Index: paramIdx,
						})
						fieldIdx := paramIdx
						_ = fieldIdx
						paramIdx++
					}
				}
			}
		}

		// Results
		if fd.Type.Results != nil {
			resultIdx := 0
			for _, field := range fd.Type.Results.List {
				expr := parseExpr(field.Type)
				expr = instantiateExpr(expr, typeParamMap)

				isErr := expr.Value == "error"
				if len(field.Names) == 0 {
					fn.Results = append(fn.Results, &models.Field{
						Name:    "",
						Type:    expr,
						Index:   resultIdx,
						IsError: isErr,
					})
					resultIdx++
				} else {
					for _, name := range field.Names {
						fn.Results = append(fn.Results, &models.Field{
							Name:    name.Name,
							Type:    expr,
							Index:   resultIdx,
							IsError: isErr,
						})
						resultIdx++
					}
				}
			}
		}

		// Check errors
		numResults := len(fn.Results)
		if numResults > 0 && fn.Results[numResults-1].IsError {
			fn.ReturnsError = true
			if numResults == 1 {
				fn.OnlyReturnsError = true
				fn.Results = nil
			} else {
				// remove error from Results slice for rendering want fields
				fn.Results = fn.Results[:numResults-1]
			}
		}

		funcs = append(funcs, fn)
	}

	return header, funcs, nil
}

func parseExpr(expr ast.Expr) *models.Expression {
	if expr == nil {
		return &models.Expression{}
	}

	switch t := expr.(type) {
	case *ast.Ident:
		return &models.Expression{Value: t.Name}
	case *ast.StarExpr:
		sub := parseExpr(t.X)
		return &models.Expression{
			Value:    "*" + sub.Value,
			IsStar:   true,
			IsWriter: sub.IsWriter,
		}
	case *ast.SelectorExpr:
		pkg := parseExpr(t.X).Value
		sel := t.Sel.Name
		val := pkg + "." + sel
		return &models.Expression{
			Value:    val,
			IsWriter: val == "io.Writer",
		}
	case *ast.ArrayType:
		sub := parseExpr(t.Elt)
		lenStr := ""
		if t.Len != nil {
			lenStr = parseExpr(t.Len).Value
		}
		return &models.Expression{Value: "[" + lenStr + "]" + sub.Value}
	case *ast.Ellipsis:
		sub := parseExpr(t.Elt)
		return &models.Expression{
			Value:      "[]" + sub.Value,
			IsVariadic: true,
		}
	case *ast.MapType:
		key := parseExpr(t.Key)
		val := parseExpr(t.Value)
		return &models.Expression{Value: "map[" + key.Value + "]" + val.Value}
	case *ast.InterfaceType:
		return &models.Expression{Value: "interface{}"}
	case *ast.StructType:
		return &models.Expression{Value: "struct{}"}
	case *ast.FuncType:
		return &models.Expression{Value: "func()"}
	case *ast.IndexExpr:
		x := parseExpr(t.X)
		idx := parseExpr(t.Index)
		return &models.Expression{Value: x.Value + "[" + idx.Value + "]"}
	case *ast.IndexListExpr:
		x := parseExpr(t.X)
		var indices []string
		for _, ix := range t.Indices {
			indices = append(indices, parseExpr(ix).Value)
		}
		return &models.Expression{Value: x.Value + "[" + strings.Join(indices, ", ") + "]"}
	case *ast.UnaryExpr:
		sub := parseExpr(t.X)
		return &models.Expression{Value: t.Op.String() + sub.Value}
	case *ast.BinaryExpr:
		x := parseExpr(t.X)
		y := parseExpr(t.Y)
		return &models.Expression{Value: x.Value + " " + t.Op.String() + " " + y.Value}
	case *ast.ParenExpr:
		sub := parseExpr(t.X)
		return &models.Expression{Value: "(" + sub.Value + ")"}
	default:
		return &models.Expression{Value: fmt.Sprintf("%v", expr)}
	}
}

func mapTypeConstraint(constraint string) string {
	if constraint == "any" {
		return "int"
	}
	if constraint == "comparable" {
		return "string"
	}
	return "string"
}

func instantiateExpr(expr *models.Expression, typeParamMap map[string]string) *models.Expression {
	if len(typeParamMap) == 0 || expr == nil {
		return expr
	}
	val := expr.Value
	for k, v := range typeParamMap {
		if val == k {
			val = v
		} else if strings.HasPrefix(val, "[]"+k) {
			val = "[]" + v
		} else if strings.HasPrefix(val, "*"+k) {
			val = "*" + v
		} else if strings.Contains(val, "["+k+"]") {
			val = strings.ReplaceAll(val, "["+k+"]", "["+v+"]")
		} else if strings.Contains(val, ", "+k) {
			val = strings.ReplaceAll(val, ", "+k, ", "+v)
		} else if strings.Contains(val, k+",") {
			val = strings.ReplaceAll(val, k+",", v+",")
		}
	}
	return &models.Expression{
		Value:      val,
		IsStar:     expr.IsStar,
		IsVariadic: expr.IsVariadic,
		IsWriter:   expr.IsWriter,
	}
}
EOF"}

