			fn.ReturnsError = true
			if numResults == 1 {
				fn.OnlyReturnsError = true
				fn.Results = nil
			} else {
				// remove error from Results slice for rendering want fields
				fn.Results = fn.Results[:numResults-1]
			}
		}

		funcs = append(funcs, fn)
	}

	return header, funcs, nil
}

func parseExpr(expr ast.Expr) *models.Expression {
	if expr == nil {
		return &models.Expression{}
	}

	switch t := expr.(type) {
	case *ast.Ident:
		return &models.Expression{Value: t.Name}
	case *ast.StarExpr:
		sub := parseExpr(t.X)
		return &models.Expression{
			Value:    "*" + sub.Value,
			IsStar:   true,
			IsWriter: sub.IsWriter,
		}
	case *ast.SelectorExpr:
		pkg := parseExpr(t.X).Value
		sel := t.Sel.Name
		val := pkg + "." + sel
		return &models.Expression{
			Value:    val,
			IsWriter: val == "io.Writer",
		}
	case *ast.ArrayType:
		sub := parseExpr(t.Elt)
		lenStr := ""
		if t.Len != nil {
			lenStr = parseExpr(t.Len).Value
		}
		return &models.Expression{Value: "[" + lenStr + "]" + sub.Value}
	case *ast.Ellipsis:
		sub := parseExpr(t.Elt)
		return &models.Expression{
			Value:      "[]" + sub.Value,
			IsVariadic: true,
		}
	case *ast.MapType:
		key := parseExpr(t.Key)
		val := parseExpr(t.Value)
		return &models.Expression{Value: "map[" + key.Value + "]" + val.Value}
	case *ast.InterfaceType:
		return &models.Expression{Value: "interface{}"}
	case *ast.StructType:
		return &models.Expression{Value: "struct{}"}
	case *ast.FuncType:
		return &models.Expression{Value: "func()"}
	case *ast.IndexExpr:
		x := parseExpr(t.X)
		idx := parseExpr(t.Index)
		return &models.Expression{Value: x.Value + "[" + idx.Value + "]"}
	case *ast.IndexListExpr:
		x := parseExpr(t.X)
		var indices []string
		for _, ix := range t.Indices {
			indices = append(indices, parseExpr(ix).Value)
		}
		return &models.Expression{Value: x.Value + "[" + strings.Join(indices, ", ") + "]"}
	case *ast.UnaryExpr:
		sub := parseExpr(t.X)
		return &models.Expression{Value: t.Op.String() + sub.Value}
	case *ast.BinaryExpr:
		x := parseExpr(t.X)
		y := parseExpr(t.Y)
		return &models.Expression{Value: x.Value + " " + t.Op.String() + " " + y.Value}
	case *ast.ParenExpr:
		sub := parseExpr(t.X)
		return &models.Expression{Value: "(" + sub.Value + ")"}
	default:
		return &models.Expression{Value: fmt.Sprintf("%v", expr)}
	}
}

func mapTypeConstraint(constraint string) string {
	if constraint == "any" {
		return "int"
	}
	if constraint == "comparable" {
		return "string"
	}
	return "string"
}

func instantiateExpr(expr *models.Expression, typeParamMap map[string]string) *models.Expression {
	if len(typeParamMap) == 0 || expr == nil {
		return expr
	}
	val := expr.Value
	for k, v := range typeParamMap {
		if val == k {
			val = v
		} else if strings.HasPrefix(val, "[]"+k) {
			val = "[]" + v
		} else if strings.HasPrefix(val, "*"+k) {
			val = "*" + v
		} else if strings.Contains(val, "["+k+"]") {
			val = strings.ReplaceAll(val, "["+k+"]", "["+v+"]")
		} else if strings.Contains(val, ", "+k) {
			val = strings.ReplaceAll(val, ", "+k, ", "+v)
		} else if strings.Contains(val, k+",") {
			val = strings.ReplaceAll(val, k+",", v+",")
		}
	}
	return &models.Expression{
		Value:      val,
		IsStar:     expr.IsStar,
		IsVariadic: expr.IsVariadic,
		IsWriter:   expr.IsWriter,
	}
}
EOF

