{"command":"cat <<'EOF' > render/render.go
package render

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"text/template"

	"gotests/models"
	"gotests/templates"
)

type Options struct {
	PrintInputs    bool
	Subtests       bool
	Parallel       bool
	Named          bool
	UseGoCmp       bool
	Template       string
	TemplateDir    string
	TemplateParams map[string]interface{}
}

type Render struct {
	opt  Options
	tmpl *template.Template
}

func New(opt Options) (*Render, error) {
	r := &Render{opt: opt}
	tmpl, err := r.loadTemplates()
	if err != nil {
		return nil, err
	}
	r.tmpl = tmpl
	return r, nil
}

func (r *Render) loadTemplates() (*template.Template, error) {
	funcMap := template.FuncMap{
		"Want": func(f *models.Field) string {
			if f == nil || f.Index == 0 {
				return "want"
			}
			return fmt.Sprintf("want%d", f.Index)
		},
		"Got": func(f *models.Field) string {
			if f == nil || f.Index == 0 {
				return "got"
			}
			return fmt.Sprintf("got%d", f.Index)
		},
		"Param": func(f *models.Field) string {
			if f == nil {
				return ""
			}
			if f.Name != "" {
				return f.Name
			}
			return fmt.Sprintf("in%d", f.Index)
		},
		"Field": func(f *models.Field) string {
			if f == nil {
				return ""
			}
			if f.Name != "" {
				return f.Name
			}
			return fmt.Sprintf("in%d", f.Index)
		},
		"Receiver": func(rec *models.Receiver) string {
			if rec == nil {
				return ""
			}
			if rec.Name != "" {
				return rec.Name
			}
			tn := rec.TypeName()
			if len(tn) == 0 {
				return "r"
			}
			return strings.ToLower(string([]rune(tn)[0]))
		},
		"isScalar": func(expr *models.Expression) bool {
			if expr == nil {
				return false
			}
			v := expr.Value
			switch v {
			case "int", "int8", "int16", "int32", "int64",
				"uint", "uint8", "uint16", "uint32", "uint64", "uintptr",
				"float32", "float64", "complex64", "complex128",
				"string", "bool", "byte", "rune":
				return true
			}
			return false
		},
	}

	tmpl := template.New("gotests").Funcs(funcMap)

	if r.opt.TemplateDir != "" {
		entries, err := os.ReadDir(r.opt.TemplateDir)
		if err != nil {
			return nil, fmt.Errorf("loading custom templates: %w", err)
		}
		var files []string
		for _, e := range entries {
			if !e.IsDir() && strings.HasSuffix(e.Name(), ".tmpl") {
				files = append(files, filepath.Join(r.opt.TemplateDir, e.Name()))
			}
		}
		if len(files) == 0 {
			return nil, fmt.Errorf("loading custom templates: tmpls.ParseFiles: template: no files named in call to ParseFiles")
		}
		t, err := tmpl.ParseFiles(files...)
		if err != nil {
			return nil, fmt.Errorf("loading custom templates: %w", err)
		}
		return t, nil
	}

	tmplName := r.opt.Template
	if tmplName == "" {
		tmplName = "default"
	}

	pattern := tmplName + "/*.tmpl"
	t, err := tmpl.ParseFS(templates.FS, pattern)
	if err != nil {
		return nil, fmt.Errorf("loading custom templates of name: %w", err)
	}
	return t, nil
}

type FunctionData struct {
	*models.Function
	PrintInputs    bool
	Subtests       bool
	Parallel       bool
	Named          bool
	UseGoCmp       bool
	TemplateParams map[string]interface{}
}

func (r *Render) Header(header *models.Header) ([]byte, error) {
	var buf bytes.Buffer
	t := r.tmpl.Lookup("header")
	if t == nil {
		return nil, fmt.Errorf("header template not found")
	}
	if err := t.Execute(&buf, header); err != nil {
		return nil, fmt.Errorf("render.Header: %w", err)
	}
	return buf.Bytes(), nil
}

func (r *Render) Function(fn *models.Function) ([]byte, error) {
	var buf bytes.Buffer
	t := r.tmpl.Lookup("function")
	if t == nil {
		return nil, fmt.Errorf("function template not found")
	}
	data := &FunctionData{
		Function:       fn,
		PrintInputs:    r.opt.PrintInputs,
		Subtests:       r.opt.Subtests,
		Parallel:       r.opt.Parallel,
		Named:          r.opt.Named,
		UseGoCmp:       r.opt.UseGoCmp,
		TemplateParams: r.opt.TemplateParams,
	}
	if err := t.Execute(&buf, data); err != nil {
		return nil, fmt.Errorf("render.TestFunction: %w", err)
	}
	return buf.Bytes(), nil
}
EOF"}

