{"command":"cat <<'EOF' > output/output.go
package output

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"

	"go/format"
	"go/token"
	"os"
	"path/filepath"
	"strings"

	"gotests/ai"
	"gotests/models"
	"gotests/render"
)

type Output struct {
	render *render.Render
	ai     *ai.Client
	write  bool
}

func New(r *render.Render, aiClient *ai.Client, write bool) *Output {
	return &Output{
		render: r,
		ai:     aiClient,
		write:  write,
	}
}

func (o *Output) Process(srcPath string, header *models.Header, funcs []*models.Function) error {
	if len(funcs) == 0 {
		fmt.Printf("No tests generated for %s\n", srcPath)
		return nil
	}

	testPath := strings.TrimSuffix(srcPath, ".go") + "_test.go"

	// Parse existing test file if present
	existingTestNames := make(map[string]bool)
	var existingContent []byte
	var existingComments []string
	if data, err := os.ReadFile(testPath); err == nil {
		existingContent = data
		fset := token.NewFileSet()
		if node, err := parser.ParseFile(fset, testPath, data, parser.ParseComments); err == nil {
			for _, decl := range node.Decls {
				if fd, ok := decl.(*ast.FuncDecl); ok {
					existingTestNames[fd.Name.Name] = true
				}
			}
			if node.Doc != nil {
				for _, c := range node.Doc.List {
					existingComments = append(comments, c.Text)
				}
			}
		}
	}

	// Filter functions that already have tests
	var newFuncs []*models.Function
	for _, fn := range funcs {
		if !existingTestNames[fn.TestName()] {
			newFuncs = append(newFuncs, fn)
		}
	}

	if len(newFuncs) == 0 {
		fmt.Printf("No tests generated for %s\n", srcPath)
		return nil
	}

	// Print Generated messages for new functions
	for _, fn := range newFuncs {
		fmt.Printf("Generated %s\n", fn.TestName())
	}

	// Collect required imports
	importsMap := make(map[string]*models.Import)
	importsMap["testing"] = &models.Import{Path: `"testing"`}

	// Check if any function needs reflect, cmp, testify assert, fmt
	for _, fn := range newFuncs {
		for _, r := range fn.Results {
			if r.Type != nil && !isScalar(r.Type) {
				// check if cmp or reflect
				// render options will dictate
			}
		}
		// Always collect imports used by types in parameters / results / receiver
		collectTypeImports(fn, header.Imports, importsMap)
	}

	// Also parse template output to discover needed imports or add standard ones
	// Add required standard imports
	var renderImports []*models.Import
	for _, imp := range importsMap {
		renderImports = append(renderImports, imp)
	}

	headerData := &models.Header{
		Package:  header.Package,
		Imports:  renderImports,
		Comments: existingComments,
	}
	if len(headerData.Comments) == 0 {
		headerData.Comments = header.Comments
	}

	// Generate code
	var codeBuf bytes.Buffer

	if len(existingContent) > 0 {
		// Existing test file exists: we will render only the new test functions and append
		for _, fn := range newFuncs {
			fnCode, err := o.render.Function(fn)
			if err != nil {
				return err
			}

			if o.ai != nil {
				if aiCases, err := o.ai.GenerateCases(fn, string(fnCode)); err == nil && aiCases != "" {
					fnCode = bytes.Replace(fnCode, []byte("// TODO: Add test cases."), []byte(aiCases), 1)
				}
			}

			codeBuf.Write(fnCode)
			codeBuf.WriteString("\n\n")
		}

		// Merge existing content with new functions and update imports
		merged, err := mergeTestFile(existingContent, codeBuf.Bytes(), importsMap)
		if err != nil {
			return err
		}

		formatted, err := format.Source(merged)
		if err != nil {
			formatted = merged
		}

		if o.write {
			return os.WriteFile(testPath, formatted, 0644)
		} else {
			fmt.Print(string(formatted))
			return nil
		}
	} else {
		// New test file
		headerCode, err := o.render.Header(headerData)
		if err != nil {
			return err
		}
		codeBuf.Write(headerCode)
		codeBuf.WriteString("\n\n")

		for _, fn := range newFuncs {
			fnCode, err := o.render.Function(fn)
			if err != nil {
				return err
			}

			if o.ai != nil {
				if aiCases, err := o.ai.GenerateCases(fn, string(fnCode)); err == nil && aiCases != "" {
					fnCode = bytes.Replace(fnCode, []byte("// TODO: Add test cases."), []byte(aiCases), 1)
				}
			}

			codeBuf.Write(fnCode)
			codeBuf.WriteString("\n\n")
		}

		formatted, err := format.Source(codeBuf.Bytes())
		if err != nil {
			// If format fails, try to fix imports or use raw
			formatted = codeBuf.Bytes()
		}

		if o.write {
			return os.WriteFile(testPath, formatted, 0644)
		} else {
			fmt.Print(string(formatted))
			return nil
		}
	}
}

func collectTypeImports(fn *models.Function, sourceImports []*models.Import, importsMap map[string]*models.Import) {
	// Look for package selectors in type expressions
	var typeStrings []string

	if fn.Receiver != nil && fn.Receiver.Type != nil {
		typeStrings = append(typeStrings, fn.Receiver.Type.Value)
	}
	for _, p := range fn.Parameters {
		if p.Type != nil {
			typeStrings = append(typeStrings, p.Type.Value)
		}
	}
	for _, r := range fn.Results {
		if r.Type != nil {
			typeStrings = append(typeStrings, r.Type.Value)
		}
	}

	for _, ts := range typeStrings {
		for _, imp := range sourceImports {
			pkgName := imp.Name
			if pkgName == "" {
				// extract last component of path e.g. "net/http" -> "http"
				p := strings.Trim(imp.Path, `"`)
				if idx := strings.LastIndex(p, "/"); idx != -1 {
					pkgName = p[idx+1:]
				} else {
					pkgName = p
				}
			}
			if strings.Contains(ts, pkgName+".") {
				importsMap[pkgName] = imp
			}
		}
	}
}

func isScalar(expr *models.Expression) bool {
	if expr == nil {
		return false
	}
	switch expr.Value {
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64", "uintptr",
		"float32", "float64", "complex64", "complex128",
		"string", "bool", "byte", "rune":
		return true
	}
	return false
}

func mergeTestFile(existingData, newFuncsData []byte, extraImports map[string]*models.Import) ([]byte, error) {
	// Parse existing test file
	fset := token.NewFileSet()
	fileNode, err := parser.ParseFile(fset, "test.go", existingData, parser.ParseComments)
	if err != nil {
		// Fallback: append
		var buf bytes.Buffer
		buf.Write(existingData)
		buf.WriteString("\n\n")
		buf.Write(newFuncsData)
		return buf.Bytes(), nil
	}

	_ = fileNode
	// Simply append new function code to existing file data and let format.Source / AST import manager format it
	var buf bytes.Buffer
	buf.Write(existingData)
	buf.WriteString("\n\n")
	buf.Write(newFuncsData)

	// Format
	res, err := format.Source(buf.Bytes())
	if err != nil {
		return buf.Bytes(), nil
	}
	return res, nil
}
EOF"}

