{"command":"cat <<'EOF' > main.go
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"gotests/ai"
	"gotests/models"
	"gotests/output"
	"gotests/parser"
	"gotests/render"
)

var (
	aiFlag                 = flag.Bool("ai", false, "generate test cases using AI (requires Ollama)")
	aiEndpoint             = flag.String("ai-endpoint", "http://localhost:11434", "Ollama API endpoint")
	aiMaxCases             = flag.Int("ai-max-cases", 10, "maximum number of test cases to generate with AI")
	aiMinCases             = flag.Int("ai-min-cases", 3, "minimum number of test cases to generate with AI")
	aiModel                = flag.String("ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation")
	allFlag                = flag.Bool("all", false, "generate tests for all functions and methods")
	exclFlag               = flag.String("excl", "", "regexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all")
	exportedFlag           = flag.Bool("exported", false, "generate tests for exported functions and methods. Takes precedence over -only and -all")
	iFlag                  = flag.Bool("i", false, "print test inputs in error messages")
	namedFlag              = flag.Bool("named", false, "switch table tests from using slice to map (with test name for the key)")
	nosubtestsFlag         = flag.Bool("nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
	onlyFlag               = flag.String("only", "", "regexp. generate tests for functions and methods that match only. Takes precedence over -all")
	parallelFlag           = flag.Bool("parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
	templateFlag           = flag.String("template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
	templateDirFlag        = flag.String("template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
	templateParamsFlag     = flag.String("template_params", "", "read external parameters to template by json with stdin")
	templateParamsFileFlag = flag.String("template_params_file", "", "read external parameters to template by json with file")
	useGoCmpFlag           = flag.Bool("use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
	versionFlag            = flag.Bool("version", false, "print version information and exit")
	wFlag                  = flag.Bool("w", false, "write output to (test) files instead of stdout")
)

func main() {
	flag.Parse()

	if *versionFlag {
		fmt.Println("gotests v0.0.0-20260611191915-db3bc27e8c01")
		fmt.Println("Go version: go1.24.5")
		fmt.Println("Git commit: db3bc27e8c01bec2e9879918c4d5fea379323219")
		fmt.Println("Build time: 2026-06-11T19:19:15Z")
		os.Exit(0)
	}

	if !*allFlag && !*exportedFlag && *onlyFlag == "" && *exclFlag == "" {
		fmt.Println("Please specify either the -only, -excl, -exported, or -all flag")
		os.Exit(0)
	}

	args := flag.Args()
	if len(args) == 0 {
		fmt.Println("Please specify a file or directory containing the source")
		os.Exit(0)
	}

	// Validate regexps
	var exclRegex *regexp.Regexp
	if *exclFlag != "" {
		var err error
		exclRegex, err = regexp.Compile(*exclFlag)
		if err != nil {
			fmt.Printf("Invalid -excl regex: %v\n", err)
			os.Exit(0)
		}
	}

	var onlyRegex *regexp.Regexp
	if *onlyFlag != "" {
		var err error
		onlyRegex, err = regexp.Compile(*onlyFlag)
		if err != nil {
			fmt.Printf("Invalid -only regex: %v\n", err)
			os.Exit(0)
		}
	}

	// Parse template params
	templateParams := make(map[string]interface{})
	if *templateParamsFileFlag != "" {
		data, err := os.ReadFile(*templateParamsFileFlag)
		if err != nil {
			fmt.Printf("Failed to read from %s ,err %v", *templateParamsFileFlag, err)
			os.Exit(0)
		}
		if err := json.Unmarshal(data, &templateParams); err != nil {
			fmt.Printf("Failed to unmarshal template_params JSON: %v", err)
			os.Exit(0)
		}
	} else if *templateParamsFlag != "" {
		if err := json.Unmarshal([]byte(*templateParamsFlag), &templateParams); err != nil {
			fmt.Printf("Failed to unmarshal template_params JSON: %v", err)
			os.Exit(0)
		}
	}

	// Template and TemplateDir resolution (check env vars)
	templateName := *templateFlag
	if templateName == "" {
		templateName = os.Getenv("GOTESTS_TEMPLATE")
	}
	templateDir := *templateDirFlag
	if templateDir == "" {
		templateDir = os.Getenv("GOTESTS_TEMPLATE_DIR")
	}

	renderOpts := render.Options{
		PrintInputs:    *iFlag,
		Subtests:       !*nosubtestsFlag,
		Parallel:       *parallelFlag,
		Named:          *namedFlag,
		UseGoCmp:       *useGoCmpFlag,
		Template:       templateName,
		TemplateDir:    templateDir,
		TemplateParams: templateParams,
	}

	rnd, err := render.New(renderOpts)
	if err != nil {
		fmt.Printf("output.Process: %v\n", err)
		os.Exit(0)
	}

	// AI Setup
	var aiClient *ai.Client
	if *aiFlag {
		fmt.Fprintf(os.Stderr, "⚠️  WARNING: Function source code will be sent to AI provider at %s\n", *aiEndpoint)
		fmt.Fprintf(os.Stderr, "   Ensure your code does not contain secrets or sensitive information.\n\n")

		aiClient = ai.New(ai.Options{
			Enabled:  true,
			Endpoint: *aiEndpoint,
			Model:    *aiModel,
			MinCases: *aiMinCases,
			MaxCases: *aiMaxCases,
		})
		if err := aiClient.CheckAvailable(); err != nil {
			fmt.Printf("output.Process: %v\n", err)
			os.Exit(0)
		}
	}

	out := output.New(rnd, aiClient, *wFlag)
	p := parser.New()

	files := expandPaths(args)
	for _, file := range files {
		header, funcs, err := p.Parse(file)
		if err != nil {
			fmt.Println(err)
			os.Exit(0)
		}

		filteredFuncs := filterFuncs(funcs, exclRegex, *exportedFlag, onlyRegex, *allFlag)
		if err := out.Process(file, header, filteredFuncs); err != nil {
			fmt.Printf("output.Process: %v\n", err)
			os.Exit(0)
		}
	}
}

func filterFuncs(funcs []*models.Function, excl *regexp.Regexp, exported bool, only *regexp.Regexp, all bool) []*models.Function {
	var res []*models.Function
	for _, fn := range funcs {
		if excl != nil {
			if matchFunc(fn, excl) {
				continue
			}
		}
		if exported {
			if !fn.IsExported {
				continue
			}
		} else if only != nil {
			if !matchFunc(fn, only) {
				continue
			}
		}
		res = append(res, fn)
	}
	return res
}

func matchFunc(fn *models.Function, re *regexp.Regexp) bool {
	if re.MatchString(fn.Name) {
		return true
	}
	if fn.Receiver != nil {
		if re.MatchString(fn.Receiver.TypeName()) {
			return true
		}
	}
	return false
}

func expandPaths(paths []string) []string {
	var files []string
	for _, path := range paths {
		if strings.HasSuffix(path, "/...") || path == "..." || path == "./..." {
			base := strings.TrimSuffix(path, "/...")
			if base == "..." || base == "." || base == "./..." {
				base = "."
			}
			filepath.Walk(base, func(p string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if info.IsDir() {
					name := info.Name()
					if (strings.HasPrefix(name, ".") && name != ".") || name == "vendor" {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(p, ".go") && !strings.HasSuffix(p, "_test.go") {
					files = append(files, p)
				}
				return nil
			})
		} else {
			fi, err := os.Stat(path)
			if err != nil {
				files = append(files, path) // Will be handled by parser error
				continue
			}
			if fi.IsDir() {
				entries, _ := os.ReadDir(path)
				for _, entry := range entries {
					if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") && !strings.HasSuffix(entry.Name(), "_test.go") {
						files = append(files, filepath.Join(path, entry.Name()))
					}
				}
			} else {
				if strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go") {
					files = append(files, path)
				}
			}
		}
	}
	return files
}
EOF"}

