	renderOpts := render.Options{
		PrintInputs:    *iFlag,
		Subtests:       !*nosubtestsFlag,
		Parallel:       *parallelFlag,
		Named:          *namedFlag,
		UseGoCmp:       *useGoCmpFlag,
		Template:       templateName,
		TemplateDir:    templateDir,
		TemplateParams: templateParams,
	}

	rnd, err := render.New(renderOpts)
	if err != nil {
		fmt.Printf("output.Process: %v\n", err)
		os.Exit(0)
	}

	// AI Setup
	var aiClient *ai.Client
	if *aiFlag {
		fmt.Fprintf(os.Stderr, "⚠️  WARNING: Function source code will be sent to AI provider at %s\n", *aiEndpoint)
		fmt.Fprintf(os.Stderr, "   Ensure your code does not contain secrets or sensitive information.\n\n")

		aiClient = ai.New(ai.Options{
			Enabled:  true,
			Endpoint: *aiEndpoint,
			Model:    *aiModel,
			MinCases: *aiMinCases,
			MaxCases: *aiMaxCases,
		})
		if err := aiClient.CheckAvailable(); err != nil {
			fmt.Printf("output.Process: %v\n", err)
			os.Exit(0)
		}
	}

	out := output.New(rnd, aiClient, *wFlag)
	p := parser.New()

	files := expandPaths(args)
	for _, file := range files {
		header, funcs, err := p.Parse(file)
		if err != nil {
			fmt.Println(err)
			os.Exit(0)
		}

		filteredFuncs := filterFuncs(funcs, exclRegex, *exportedFlag, onlyRegex, *allFlag)
		if err := out.Process(file, header, filteredFuncs); err != nil {
			fmt.Printf("output.Process: %v\n", err)
			os.Exit(0)
		}
	}
}

func filterFuncs(funcs []*models.Function, excl *regexp.Regexp, exported bool, only *regexp.Regexp, all bool) []*models.Function {
	var res []*models.Function
	for _, fn := range funcs {
		if excl != nil {
			if matchFunc(fn, excl) {
				continue
			}
		}
		if exported {
			if !fn.IsExported {
				continue
			}
		} else if only != nil {
			if !matchFunc(fn, only) {
				continue
			}
		}
		res = append(res, fn)
	}
	return res
}

func matchFunc(fn *models.Function, re *regexp.Regexp) bool {
	if re.MatchString(fn.Name) {
		return true
	}
	if fn.Receiver != nil {
		if re.MatchString(fn.Receiver.TypeName()) {
			return true
		}
	}
	return false
}

func expandPaths(paths []string) []string {
	var files []string
	for _, path := range paths {
		if strings.HasSuffix(path, "/...") || path == "..." || path == "./..." {
			base := strings.TrimSuffix(path, "/...")
			if base == "..." || base == "." || base == "./..." {
				base = "."
			}
			filepath.Walk(base, func(p string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if info.IsDir() {
					name := info.Name()
					if (strings.HasPrefix(name, ".") && name != ".") || name == "vendor" {
						return filepath.SkipDir
					}
					return nil
				}
				if strings.HasSuffix(p, ".go") && !strings.HasSuffix(p, "_test.go") {
					files = append(files, p)
				}
				return nil
			})
		} else {
			fi, err := os.Stat(path)
			if err != nil {
				files = append(files, path) // Will be handled by parser error
				continue
			}
			if fi.IsDir() {
				entries, _ := os.ReadDir(path)
				for _, entry := range entries {
					if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") && !strings.HasSuffix(entry.Name(), "_test.go") {
						files = append(files, filepath.Join(path, entry.Name()))
					}
				}
			} else {
				if strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go") {
					files = append(files, path)
				}
			}
		}
	}
	return files
}
